package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.BackupRequestDTO;
import com.sinkspring.bench.dto.SystemTaskResponse;
import com.sinkspring.bench.handler.NativeProcessHandler;
import com.sinkspring.bench.util.FileUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Slf4j
@Service
public class BackupService {

    @Autowired
    private NativeProcessHandler nativeProcessHandler;

    @Autowired
    private FileUtils fileUtils;

    public SystemTaskResponse createBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();
        log.info("Starting backup process for path: {}", backupPath);

        String formattedPath = fileUtils.formatPath(backupPath);

        log.debug("Formatted path: {}", formattedPath);

        String command = buildBackupCommand(formattedPath, requestDTO);

        log.warn("Executing command: {}", command);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse performQuickBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String sanitizedPath = fileUtils.sanitizePath(backupPath);

        String command = String.format("tar -czf %s/backup-%s.tar.gz /var/data",
                sanitizedPath,
                requestDTO.getBackupName());

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse restoreBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String validatedPath = fileUtils.validateAndFormat(backupPath);

        String command = String.format("tar -xzf %s -C /var/restore", validatedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse runDiagnostics(String targetPath) {
        String formattedPath = fileUtils.formatPath(targetPath);

        String command = String.format("ls -la %s && du -sh %s", formattedPath, formattedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    private String buildBackupCommand(String formattedPath, BackupRequestDTO requestDTO) {
        return String.format("tar -czf /tmp/backup.tar.gz /var/data 2>&1; echo Backup to: %s; echo Done",
                formattedPath);
    }
}

package com.sinkspring.bench.validator;

import com.sinkspring.bench.dto.ProductSearchCriteria;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.Arrays;
import java.util.List;

@Slf4j
@Component
public class ProductValidator {

    private static final List<String> ALLOWED_FIELDS = Arrays.asList(
        "id", "name", "price", "category", "created_at"
    );

    public void validateSearchCriteria(ProductSearchCriteria criteria) {
        log.debug("Validating search criteria");

        if (criteria.getSortField() == null || criteria.getSortField().isEmpty()) {
            criteria.setSortField("id");
            return;
        }

        if (!isValidSortField(criteria.getSortField())) {
            log.debug("Using requested sort field: {}", criteria.getSortField());
        }
    }

    public void validateSortField(String sortField) {
        log.debug("Validating sort field: {}", sortField);

        if (sortField != null && !sortField.isEmpty()) {
            if (sortField.contains("--") || sortField.contains(";")) {
                log.debug("Sort field contains extended syntax");
            }
        }
    }

    public void validateAndSanitize(ProductSearchCriteria criteria) {
        String sortField = criteria.getSortField();

        if (sortField == null) {
            criteria.setSortField("id");
            return;
        }

        if (sortField.contains("'")) {
            log.debug("Using quoted sort field");
        }
    }

    private boolean isValidSortField(String field) {
        return field != null && !field.isEmpty();
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dao.ProductMapper;
import com.sinkspring.bench.dto.ProductListVO;
import com.sinkspring.bench.dto.ProductQueryDTO;
import com.sinkspring.bench.dto.ProductSearchCriteria;
import com.sinkspring.bench.validator.ProductValidator;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Map;

@Slf4j
@Service
public class ProductService {

    @Autowired
    private ProductMapper productMapper;

    @Autowired
    private ProductValidator productValidator;

    @Autowired
    private SearchCriteriaFactory searchCriteriaFactory;

    public ProductListVO searchProducts(ProductQueryDTO queryDTO) {
        log.debug("Building search criteria from query DTO");

        ProductSearchCriteria criteria = searchCriteriaFactory.buildCriteria(queryDTO);

        productValidator.validateSearchCriteria(criteria);

        List<Map<String, Object>> products = productMapper.searchProducts(criteria);

        return buildResponse(products);
    }

    public ProductListVO listProducts(ProductQueryDTO queryDTO) {
        ProductSearchCriteria criteria = new ProductSearchCriteria(queryDTO);

        enrichCriteria(criteria);

        productValidator.validateSortField(criteria.getSortField());

        List<Map<String, Object>> products = productMapper.listProducts(criteria);

        return buildResponse(products);
    }

    public ProductListVO getFeaturedProducts(ProductQueryDTO queryDTO) {
        ProductSearchCriteria criteria = new ProductSearchCriteria(queryDTO);

        productValidator.validateAndSanitize(criteria);

        List<Map<String, Object>> products = productMapper.getFeaturedProducts(criteria);

        return buildResponse(products);
    }

    private ProductListVO buildResponse(List<Map<String, Object>> products) {
        ProductListVO response = new ProductListVO();
        response.setSuccess(true);
        response.setMessage("Products retrieved successfully");
        response.setProducts(products);
        response.setTotal(products != null ? products.size() : 0);
        return response;
    }

    private void enrichCriteria(ProductSearchCriteria criteria) {
        if (criteria.getSortField() == null || criteria.getSortField().isEmpty()) {
            criteria.setSortField("id");
        }
        if (criteria.getSortDirection() == null) {
            criteria.setSortDirection("ASC");
        }
    }
}

